        total_weight = math.fsum(weights)
    except (OverflowError, ValueError) as exc:
        raise FloatingPointError(
            "non-finite value encountered during brier-score computation"
        ) from exc
    if not math.isfinite(total_weight):
        raise FloatingPointError(
            "non-finite value encountered during brier-score computation"
        )
    if total_weight <= 0.0:
